-- Phase 3.3: append-only, idempotent study goals and plan history.
create table if not exists public.study_plan_events (
 server_sequence bigint generated by default as identity primary key,event_id uuid not null unique,user_id uuid not null references auth.users(id) on delete cascade,
 device_id uuid not null,platform text not null check(platform in ('web','android','ios')),event_kind text not null check(event_kind in ('goal','enrollment','completion','change')),
 payload jsonb not null,created_at timestamptz not null default now());
create index if not exists study_plan_events_user_sequence on public.study_plan_events(user_id,server_sequence);
alter table public.study_plan_events enable row level security;
drop policy if exists "study_plan_events_select_own" on public.study_plan_events;
create policy "study_plan_events_select_own" on public.study_plan_events for select to authenticated using((select auth.uid())=user_id);
create or replace function public.submit_study_plan_event(p_event_id uuid,p_device_id uuid,p_platform text,p_payload jsonb)
returns table(server_sequence bigint,accepted boolean,total_xp integer) language plpgsql security definer set search_path='' as $$
declare v_user uuid:=auth.uid();v_kind text:=p_payload->>'kind';v jsonb:=p_payload->'value';v_seq bigint;
begin
 if v_user is null then raise exception 'Authentication required';end if;
 if p_platform not in ('web','android','ios') or v_kind not in ('goal','enrollment','completion','change') or jsonb_typeof(v)<>'object' then raise exception 'Invalid event';end if;
 if length(v::text)>250000 or coalesce(v->>'id','')='' or char_length(v->>'id')>200 then raise exception 'Invalid payload';end if;
 if v_kind='goal' and (v->>'metric' not in ('minutes','lessons','reviews','checkpoints','chapters','concepts','units') or v->>'cadence' not in ('daily','weekly') or jsonb_typeof(v->'target')<>'number' or (v->>'target')::numeric not between 1 and 1440 or jsonb_typeof(v->'active')<>'boolean') then raise exception 'Invalid goal';end if;
 if v_kind='enrollment' and (v->>'status' not in ('not-started','active','paused','completed','archived') or v->>'translationId'<>'almeida-1819' or jsonb_typeof(v->'stepsSnapshot')<>'array' or jsonb_array_length(v->'stepsSnapshot') not between 1 and 1500 or jsonb_typeof(v->'studyWeekdays')<>'array' or jsonb_array_length(v->'studyWeekdays')<1) then raise exception 'Invalid enrollment';end if;
 if v_kind='completion' and (coalesce(v->>'enrollmentId','')='' or coalesce(v->>'stepId','')='' or jsonb_typeof(v->'completed')<>'boolean' or coalesce(v->>'localDate','') !~ '^\d{4}-\d{2}-\d{2}$') then raise exception 'Invalid completion';end if;
 if v_kind='change' and (coalesce(v->>'enrollmentId','')='' or v->>'kind' not in ('created','paused','resumed','archived','rescheduled','completed')) then raise exception 'Invalid change';end if;
 insert into public.study_plan_events(event_id,user_id,device_id,platform,event_kind,payload) values(p_event_id,v_user,p_device_id,p_platform,v_kind,v)
 on conflict(event_id) do nothing returning study_plan_events.server_sequence into v_seq;
 if v_seq is null then select e.server_sequence into v_seq from public.study_plan_events e where e.event_id=p_event_id and e.user_id=v_user;
  return query select v_seq,false,coalesce((select s.total_xp from public.user_stats s where s.user_id=v_user),0);return;end if;
 return query select v_seq,true,coalesce((select s.total_xp from public.user_stats s where s.user_id=v_user),0);
end;$$;
revoke all on function public.submit_study_plan_event(uuid,uuid,text,jsonb) from public;
grant execute on function public.submit_study_plan_event(uuid,uuid,text,jsonb) to authenticated;
